// SPDX-License-Identifier: EPL-2.0
/**
 * Expected results for the T5 quad_prog_vpsc tests, captured from a native
 * harness that links the oracle's own lib/neatogen and lib/vpsc (graphviz
 * 16.1.0) and calls initCMajVPSC, constrained_majorization_vpsc,
 * generateNonoverlapConstraints, removeoverlaps and deleteCMajEnvVPSC in the
 * listed order on one environment.
 *
 * Build: clang -O3 -DNDEBUG -flto=thin -arch arm64 -DDIGCOLA -DIPSEPCOLA (C
 * harness, gnu17) plus a gnu++17 helper that reads Constraint fields, linked
 * against build/lib/neatogen/libneatogen.a, build/lib/vpsc/libvpsc.a,
 * libcommon.a, libpack.a, liblabel.a, librbtree.a, libortho.a, libsfdpgen.a
 * and -lgvc -lcgraph -lcdt -lpathplan -lgts -lglib-2.0. The harness copies of
 * the four functions disassemble to the same instruction and float-op
 * sequence as libgvplugin_neato_layout.8.0.15.dylib's.
 *
 * Input rules the harness follows (the C depends on them):
 * - `srand(seed)` (SRAND op; `csrand` here) before every initCMajVPSC with
 *   diredges 2: compute_y_coords starts from init_vec_orth1's rand() vector,
 *   so the DiG-CoLa level count depends on the rand state.
 * - all nodes' ewgts are ONE contiguous allocation, as makeGraphData builds
 *   them: compute_y_coords restores per-node pointers by walking
 *   graph[0].ewgts.
 * Floats are printed as %.17g of the float value; constraint gaps are doubles.
 * Inputs are seeded pseudo-random (mulberry32). Generated data: do not
 * hand-edit (generator and harness are archived under plans/).
 *
 * Native output on a tie varies run to run with heap addresses. "cluster dir0"
 * holds the native variant e665a3280a1a (about 1 run in 10: a pass of
 * `IncVPSC::splitBlocks` goes on to visit a split's new blocks, as the port's
 * Set does); only its fourth step differs from the commoner f3685bd04945
 * (part-8 AD-8).
 */

import type { IpsepOptions } from '../quad-prog-vpsc.js';
import type { DirectedVtxData } from '../opt-arrangement.js';

/** One harness step and its native result. */
export type VpscOp =
  | { readonly op: 'INIT'; readonly diredges: 0 | 1 | 2;
      readonly expect: { nv: number; nldv: number; ndv: number; gm: number; m: number } | null }
  | { readonly op: 'CMV'; readonly iters: number; readonly b: readonly number[]; readonly place: readonly number[];
      readonly expect: { ret: number; place: readonly number[] } }
  | { readonly op: 'GNC'; readonly scale: number; readonly k: 0 | 1; readonly tc: boolean;
      readonly coords: readonly (readonly number[])[];
      readonly expect: { m: number; gm: number; cs: readonly (readonly number[])[]; bb: readonly (readonly number[])[] } }
  | { readonly op: 'CMVK'; readonly iters: number; readonly b: readonly number[];
      readonly expect: { ret: number; place: readonly number[] } }
  | { readonly op: 'GNCK'; readonly scale: number; readonly k: 0 | 1; readonly tc: boolean; readonly x: readonly number[];
      readonly expect: { m: number; gm: number; cs: readonly (readonly number[])[]; bb: readonly (readonly number[])[] } }
  | { readonly op: 'SRAND'; readonly seed: number }
  | { readonly op: 'DEL' }
  | { readonly op: 'RM'; readonly coords: readonly (readonly number[])[];
      readonly expect: { x: readonly number[]; y: readonly number[] } };

/** One harness case: header (graph, options, matrix) plus its steps. */
export interface VpscCase {
  readonly name: string;
  /** Variables, including the two cluster boundary variables per cluster. */
  readonly n: number;
  readonly clusters: readonly (readonly number[])[];
  readonly toplevel: readonly number[];
  readonly edgeGap: number;
  readonly gap: readonly [number, number];
  readonly nsize: readonly (readonly [number, number])[];
  readonly graph: readonly { edges: number[]; ewgts: number[]; edists: number[] }[] | null;
  /** Packed upper-triangular float matrix (row-wise), or null. */
  readonly packed: readonly number[] | null;
  readonly ops: readonly VpscOp[];
}

